// Launcher icons that follow the app theme, as in super-badger and super-chat.
//
// android/ is generated by `expo prebuild`, so instead of committing manifest
// edits this plugin applies them on every prebuild:
//   - copies the per-theme icons tools/appart generated (plugins/res) into
//     android/app/src/main/res
//   - moves the launcher entry off MainActivity onto one <activity-alias> per
//     theme, each with its own icon; IconDark is enabled by default and
//     modules/app-icon enables whichever matches the current theme.
const fs = require('fs');
const path = require('path');
const { withAndroidManifest, withDangerousMod } = require('expo/config-plugins');

const THEMES = ['light', 'dark', 'slate', 'sepia', 'ember'];
const DEFAULT_THEME = 'dark';

function copyDir(src, dest) {
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);
    if (entry.isDirectory()) copyDir(from, to);
    else fs.copyFileSync(from, to);
  }
}

function withThemedIconResources(config) {
  return withDangerousMod(config, [
    'android',
    async (config) => {
      const src = path.join(config.modRequest.projectRoot, 'plugins', 'res');
      if (!fs.existsSync(src)) {
        throw new Error('plugins/res is missing: run `go run ./appart` in tools/ first');
      }
      copyDir(src, path.join(config.modRequest.platformProjectRoot, 'app', 'src', 'main', 'res'));
      return config;
    },
  ]);
}

function isLauncherFilter(filter) {
  const actions = (filter.action ?? []).map((a) => a.$['android:name']);
  const categories = (filter.category ?? []).map((c) => c.$['android:name']);
  return actions.includes('android.intent.action.MAIN') && categories.includes('android.intent.category.LAUNCHER');
}

function withThemedIconAliases(config) {
  return withAndroidManifest(config, (config) => {
    const app = config.modResults.manifest.application?.[0];
    if (!app) throw new Error('AndroidManifest.xml has no <application>');
    const main = (app.activity ?? []).find((a) => a.$['android:name'] === '.MainActivity');
    if (!main) throw new Error('AndroidManifest.xml has no .MainActivity');

    main['intent-filter'] = (main['intent-filter'] ?? []).filter((f) => !isLauncherFilter(f));

    const capitalized = (t) => t[0].toUpperCase() + t.slice(1);
    const names = new Set(THEMES.map((t) => `.Icon${capitalized(t)}`));
    app['activity-alias'] = [
      ...(app['activity-alias'] ?? []).filter((a) => !names.has(a.$['android:name'])),
      ...THEMES.map((t) => ({
        $: {
          'android:name': `.Icon${capitalized(t)}`,
          'android:targetActivity': '.MainActivity',
          'android:label': '@string/app_name',
          'android:icon': `@mipmap/ic_launcher_${t}`,
          'android:roundIcon': `@mipmap/ic_launcher_${t}_round`,
          'android:enabled': t === DEFAULT_THEME ? 'true' : 'false',
          'android:exported': 'true',
        },
        'intent-filter': [
          {
            action: [{ $: { 'android:name': 'android.intent.action.MAIN' } }],
            category: [{ $: { 'android:name': 'android.intent.category.LAUNCHER' } }],
          },
        ],
      })),
    ];
    return config;
  });
}

module.exports = function withAppIcon(config) {
  return withThemedIconAliases(withThemedIconResources(config));
};
